{"function":"() => {
  // Let's parse all rows on the page carefully
  const rows = Array.from(document.querySelectorAll('tbody tr, .a-box-group, [id^="order-"]')).filter(r => r.innerText.includes('ASIN:'));

  // Or better, extract structured data from each order card
  const cards = [];
  const links = Array.from(document.querySelectorAll('a[href*="/orders-v3/order/"]'));

  links.forEach(link => {
    let container = link;
    while (container && container.parentElement && !container.classList.contains('a-box') && container.tagName !== 'TR') {
      container = container.parentElement;
    }
    const fullText = container ? container.innerText : '';

    // Extract fields
    const orderId = link.innerText.trim();

    // Date
    const dateMatch = fullText.match(/(\d{4}\/\d{2}\/\d{2}[\s\S]*?\d{2}:\d{2}\s*(?:PDT|PST)?)/);
    const orderDate = dateMatch ? dateMatch[1].replace(/\n/g, ' ').trim() : '';

    // Relative time
    const relTimeMatch = fullText.match(/(\d+\s*(?:小时|分钟|天)\s*前)/);
    const relTime = relTimeMatch ? relTimeMatch[1] : '';

    // ASIN
    const asinMatch = fullText.match(/ASIN:\s*([A-Z0-9]{10})/i);
    const asin = asinMatch ? asinMatch[1] : '';

    // SKU
    const skuMatch = fullText.match(/SKU:\s*([^\n\r]+)/);
    const sku = skuMatch ? skuMatch[1].trim() : '';

    // Qty
    const qtyMatch = fullText.match(/数量:\s*(\d+)/);
    const qty = qtyMatch ? parseInt(qtyMatch[1], 10) : 1;

    // Subtotal
    const priceMatch = fullText.match(/商品小计:\s*([A-Z]*\$[0-9\.,]+)/);
    const price = priceMatch ? priceMatch[1] : '';

    // Fulfillment
    const fulfillmentMatch = fullText.match(/配送渠道:\s*([^\n\r]+)/);
    const fulfillment = fulfillmentMatch ? fulfillmentMatch[1].trim() : '';

    // Sales channel
    const channelMatch = fullText.match(/销售渠道:\s*([^\n\r]+)/);
    const channel = channelMatch ? channelMatch[1].trim() : '';

    // Buyer / Business buyer
    const isBusiness = fullText.includes('企业买家');
    const buyerMatch = fullText.match(/买家姓名:\s*([^\n\r]+)/);
    const buyer = buyerMatch ? buyerMatch[1].trim() : '';

    // Status
    let status = '未知';
    if (fullText.includes('等待中') || fullText.includes('等待付款验证')) status = '等待中 (Pending)';
    else if (fullText.includes('未发货')) status = '未发货 (Unshipped)';
    else if (fullText.includes('付款完成') || fullText.includes('已发货')) status = '付款完成/已发货';
    else if (fullText.includes('已取消')) status = '已取消';

    // Title
    const titleLink = container ? container.querySelector('a[href*="/dp/"], a[href*="/gp/product/"]') : null;
    const title = titleLink ? titleLink.innerText.trim() : '';

    cards.push({
      orderId,
      orderDate,
      relTime,
      asin,
      sku,
      title: title.slice(0, 80),
      qty,
      price,
      fulfillment,
      channel,
      isBusiness,
      buyer,
      status
    });
  });

  return cards;
}","pageId":12,"toolSummary":"Parse structured order data"}

