  const text = document.body.innerText;
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);

  // Find lines that match date format YYYY/M/D or YYYY/MM/DD
  const dateRegex = /^\d{4}\/\d{1,2}\/\d{1,2}$/;
  const days = [];

  for (let i = 0; i < lines.length; i++) {
    if (dateRegex.test(lines[i])) {
      const date = lines[i];
      const sales = lines[i+1];
      const b2bSales = lines[i+2];
      const units = lines[i+3];
      const b2bUnits = lines[i+4];
      days.push({ date, sales, b2bSales, units, b2bUnits });
    }
  }

  let totalSales = 0;
  let totalUnits = 0;
  let totalB2bSales = 0;
  let totalB2bUnits = 0;

  days.forEach(d => {
    totalSales += parseFloat((d.sales || '0').replace(/[^0-9\.]/g, '')) || 0;
    totalB2bSales += parseFloat((d.b2bSales || '0').replace(/[^0-9\.]/g, '')) || 0;
    totalUnits += parseInt((d.units || '0').replace(/[^0-9]/g, ''), 10) || 0;
    totalB2bUnits += parseInt((d.b2bUnits || '0').replace(/[^0-9]/g, ''), 10) || 0;
  });

  return {
    daysCount: days.length,
    totalSales: totalSales.toFixed(2),
    totalUnits,
    totalB2bSales: totalB2bSales.toFixed(2),
    totalB2bUnits,
    latestDays: days.slice(-5)
  };
}","pageId":12,"toolSummary":"Parse days from text"}

