  function findInputsInShadow(root) {
    let results = [];
    const elements = root.querySelectorAll('*');
    for (const el of elements) {
      if (el.tagName === 'INPUT' && el.type === 'file') {
        results.push({ tag: el.tagName, id: el.id, accept: el.accept });
      }
      if (el.shadowRoot) {
        results = results.concat(findInputsInShadow(el.shadowRoot));
      }
    }
    return results;
  }
  const shadowInputs = findInputsInShadow(document);
  return { shadowInputs };
}","pageId":3,"toolSummary":"Check file inputs in Shadow DOM"}

