      if (f.contentDocument && f.contentDocument.body.innerText.includes('上传视频')) {
        chIframe = f;
        break;
      }
    } catch(e) {}
  }
  if (!chIframe) return { error: 'iframe cross-origin or not found' };

  const doc = chIframe.contentDocument;
  const brandSelect = doc.querySelector('select[name*="brand"], [id*="brand"]');
  const langSelect = doc.querySelector('select[name*="language"], [id*="language"]');
  const typeRadios = Array.from(doc.querySelectorAll('input[type="radio"], [role="radio"]')).map(r => r.value || r.innerText);

  return {
    brandFound: !!brandSelect,
    langFound: !!langSelect,
    typeRadios: typeRadios
  };
}",
  "pageId": 6
}
